cd /work && python3 - <<'EOF'
import json, importlib.util
spec = importlib.util.spec_from_file_location("m", "/work/submission/main.py")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
L=40; NL=12
nid=L; layers=[]
for _ in range(NL):
    layers.append([nid,nid+1]); nid+=2
dest=nid; n=nid+1
edges=[]
def add(u,v,lab): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":lab})
for i in range(L-1): add(i,i+1,"c%d"%(i%10))
for v in layers[0]: add(L-1,v,"L0")
for i in range(NL-1):
    for u in layers[i]:
        for v in layers[i+1]: add(u,v,"M%d"%(i%10))
for u in layers[-1]: add(u,dest,"z")
rounds=[{"launch_us":0,"timeout_us":1000000,"host_delay_us":1,"drop_host_ack":False,"drop_ping":[],"drop_ack":[]} for _ in range(48)]
doc={"version":1,"n":n,"capacity":[48]*n,"edges":edges,"rounds":rounds}
try:
    v=m.validate(doc)
    print("validate OK")
    res=m.simulate(v[0],v[1],v[2],v[3])
    print("simulate OK")
    out=[[] for _ in range(n)]
    for i,e in enumerate(v[2]): out[e[0]].append(i)
    c,s=m.build_classes(n,v[2],out,res["source_proof"],[res["host_delivery_us"][i] is not None for i in range(48)])
    print("classes OK", len(c))
except Exception as e:
    import traceback; traceback.print_exc()
EOF
